fun check() {
    val me = node?.let { coord.get(it) }
    if (me == null) { isLeader = false; return }          // the session expired and took the node
    val queue = coord.children(electionPath)               // sorted by sequence number
    val i = queue.indexOfFirst { it.path == me.path }
    if (i == 0) {
        isLeader = true
        token = me.createRevision                           // the fencing token
        return
    }
    isLeader = false
    watchesSet++
    coord.watch(queue[i - 1].path) { onWatch() }           // only the one just before us: no herd
}
